from collections import deque

def transform(grid):
 h=len(grid); w=len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); pts=[]
    while q:
     y,x=q.pop(); pts.append((y,x))
     for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
      yy,xx=y+dy,x+dx
      if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
       seen.add((yy,xx));q.append((yy,xx))
    minr=min(y for y,x in pts); minc=min(x for y,x in pts)
    shape=[(y-minr,x-minc) for y,x in pts]
    comps.append((minc,col,shape,max(y for y,x in shape)+1,max(x for y,x in shape)+1))
 comps.sort()
 out=[[0]*w for _ in range(h)]; r=c=0
 for i,(_,col,shape,hh,ww) in enumerate(comps):
  for y,x in shape:
   if r+y<h and c+x<w: out[r+y][c+x]=col
  if i<len(comps)-1: r+=hh-1; c+=ww-1
 return out

